    Bug 537342 - Add unified folders when favourite folders are built. r=mkmelin

    Based on https://github.com/Betterbird/thunderbird-patches/blob/main/128/features/feature-537342-unified-as-favourite.patch

    Differential Revision: https://phabricator.services.mozilla.com/D233380

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index e935d38fc47..9ee789fab51 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -2096,6 +2096,18 @@ var folderPane = {
       }
       mode.initServer(account.incomingServer);
     }
+
+    if (mode.name == "favorite") {
+      // Add favorite unified folders as well.
+      const smartServer = MailServices.accounts.findServer(
+        "nobody",
+        "smart mailboxes",
+        "none"
+      );
+      if (smartServer) {
+        mode.initServer(smartServer);
+      }
+    }
   },

   /**
diff --git a/mail/base/test/browser/browser_folderTreeQuirks.js b/mail/base/test/browser/browser_folderTreeQuirks.js
index ee5f3f1e99e..d058b1a9e37 100644
--- a/mail/base/test/browser/browser_folderTreeQuirks.js
+++ b/mail/base/test/browser/browser_folderTreeQuirks.js
@@ -553,6 +553,25 @@ add_task(async function testSmartFolders() {
     trashFolder,
     ...localExtraFolders,
   ]);
+
+  // Check that marking a unified folder as favorite works and is persistent.
+  const smartMailboxes = { URI: "mailbox://nobody@smart%20mailboxes" };
+  folderPane.activeModes = ["smart", "favorite"];
+  await checkModeListItems("favorite", []);
+
+  smartInbox.setFlag(Ci.nsMsgFolderFlags.Favorite);
+  await checkModeListItems("favorite", [smartMailboxes, smartInbox]);
+
+  folderPane.activeModes = ["smart"];
+  folderPane.activeModes = ["favorite"];
+  await checkModeListItems("favorite", [smartMailboxes, smartInbox]);
+
+  smartInbox.clearFlag(Ci.nsMsgFolderFlags.Favorite);
+  await checkModeListItems("favorite", []);
+
+  folderPane.activeModes = ["smart"];
+  folderPane.activeModes = ["smart", "favorite"];
+  await checkModeListItems("favorite", []);
 });

 /**
